 *       {@code download} then {@code activate} in one call, with {@code download}'s rejections
 *       ({@code switched: false} when the version is already running)
 *   <li>{@code booted({ version? }) → { confirmed }}: confirms the UI on its trial launch,
 *       cancelling the watchdog, when {@code version} (the page's own UI version) is that UI; a
 *       call from another page is ignored
 *   <li>{@code reset()}: back to the bundled UI; during a download it cancels the download first
 * </ul>
 *
 * <p>Only {@code activate} and {@code apply} switch versions: a staged version is never started
 * on its own. The trial watchdog counts foreground time only: it pauses in {@code onPause} and
 * resumes with the time left in {@code onResume}.
 */
@CapacitorPlugin(name = "DenextOta")
public class DenextOtaPlugin extends Plugin {

    private final Handler mainHandler = new Handler(Looper.getMainLooper());
    private final ExecutorService downloads = Executors.newSingleThreadExecutor();
    /** Main-thread only. Set while download or apply downloads, so a second one cannot race it. */
    private boolean applying = false;
    /** Main-thread only. Reset calls waiting for the download in flight to stop. */
    private final List<PluginCall> pendingResets = new ArrayList<>();
    /** Main-thread only. Rolls a UI on its trial launch back unless booted cancels it. */
    @Nullable
    private Runnable watchdog;
    /** Main-thread only. When the armed watchdog fires ({@link SystemClock#uptimeMillis}). */
    private long watchdogDeadline = 0;
    /** Main-thread only. The watchdog time left while the app is paused, or -1. */
