// denext-ota-template: 3 sha256=e19a385df72b0035393870933abe1e71da4f1b8967b878d9640138b7ab25c0d0
// Generated by `denext mobile add-ota` (denext over-the-air UI updates). Safe to commit;
// re-run `denext mobile add-ota` after upgrading denext (then ship a new binary). See
// https://denext.dev/docs/desktop.

package dev.denext.ota;

import android.content.Context;
import com.getcapacitor.Bridge;
import com.getcapacitor.ServerPath;
import java.io.File;

/**
 * Wires denext's over-the-air UI into a Capacitor {@code BridgeActivity}. Call it from
 * {@code MainActivity.onCreate} BEFORE {@code super.onCreate}, which builds the bridge:
 *
 * <pre>{@code
 * public class MainActivity extends BridgeActivity {
 *     @Override
 *     protected void onCreate(Bundle savedInstanceState) {
 *         DenextOta.prepare(this, bridgeBuilder);
 *         super.onCreate(savedInstanceState);
 *     }
 * }
 * }</pre>
 *
 * It registers {@link DenextOtaPlugin} and points the bridge at the UI to start from: a
 * confirmed or trial over-the-air UI, else the bundled {@code public/}. A trial the app died
 * in twice is rolled back here, before the first page loads. {@code bridgeBuilder} is the
 * activity's own protected field, which is why the activity passes it in.
 *
 * <p>A WebView renderer that dies during a trial takes the app process with it (Capacitor does
 * not handle {@code onRenderProcessGone}); the next launch counts that as a failed trial attempt.
 */
public final class DenextOta {

    private DenextOta() {}

    /**
     * Registers the plugin and picks the start directory.
     *
     * @param context the activity (any context of the app works)
     * @param bridgeBuilder the activity's {@code bridgeBuilder}
     */
    public static void prepare(Context context, Bridge.Builder bridgeBuilder) {
        bridgeBuilder.addPlugin(DenextOtaPlugin.class);
        File directory = DenextOtaStore.get(context).startDirectory();
        if (directory != null) {
            bridgeBuilder.setServerPath(new ServerPath(ServerPath.PathType.BASE_PATH, directory.getAbsolutePath()));
        }
    }
}

